		},
	},
	webAnalyticsConfiguration:{
		autoCapture: {
			scroll: true,
			pageView: true,
			onLoad: true,
			onUnload: true,
			click: true,
			resize: true,
			jsError: true
		},
		coreData: {"pageName":"404","pageType":"404"},
		urlCollectQuery: true,
		urlCollectHash: true,
	},
	customProperties: {
		_mkto_trk: function() {
			return document.cookie.replace(/(?:(?:^|.*;\s*)_mkto_trk\s*\=\s*([^;]*).*$)|^.*$/, "$1");
		}
	}
};
// Initialize OneDS SDK
analytics.initialize( config, [] );
